<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myproject/src/index.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myproject/src/index.js.bak</span></span>
